import crypto from 'node:crypto'
import { formatPktDateTime } from './pkTime.js'

/**
 * Reference generation.
 *
 * All references are generated by the server. The client never supplies a
 * transaction reference, order number or gateway reference.
 *
 * The character set omits look-alike characters (0/O, 1/I/L) so a reference
 * can be read out loud or copied from a screenshot without mistakes.
 */

const ALPHABET = '23456789ABCDEFGHJKLMNPQRSTUVWXYZ'

/**
 * Build a random reference of the given length.
 *
 * @param {number} length
 * @returns {string}
 */
export function randomCode(length = 8) {
  const bytes = crypto.randomBytes(length)
  let code = ''

  for (let index = 0; index < length; index += 1) {
    code += ALPHABET[bytes[index] % ALPHABET.length]
  }

  return code
}

/**
 * Internal PayLab transaction reference, e.g. "PAYLAB-TXN-7FK2M9QX".
 */
export function generateTransactionReference() {
  return `PAYLAB-TXN-${randomCode(8)}`
}

/**
 * Demo order number, e.g. "PAYLAB-DEMO-4H7K2M9Q".
 */
export function generateOrderNumber() {
  return `PAYLAB-DEMO-${randomCode(8)}`
}

/**
 * Clearly labelled *simulated* gateway reference.
 *
 * The "SIM-" prefix makes it obvious that this reference was produced by the
 * local simulator and is not an official JazzCash or Easypaisa transaction
 * id.
 *
 * @param {string} gateway canonical gateway name, e.g. "JAZZCASH"
 */
export function generateSimulatedGatewayReference(gateway) {
  return `SIM-MOCK-${String(gateway).toUpperCase()}-${randomCode(8)}`
}

/**
 * Identifier used to correlate a request across the logs.
 */
export function generateRequestId() {
  return crypto.randomUUID()
}

/**
 * The reference sent to a real gateway.
 *
 * Both gateways require letters and digits only:
 *   JazzCash  pp_TxnRefNo   max 20 characters
 *   Easypaisa orderRefNum   max 50 characters
 *
 * The value is stored on the transaction and is the key a callback is matched
 * against, so it must be unique per attempt.
 *
 * @param {string} gateway canonical gateway name
 * @returns {string}
 */
export function generateGatewayTxnRef(gateway) {
  const stamp = formatPktDateTime()

  if (gateway === 'JAZZCASH') {
    // T + yyyyMMddHHmmss + 5 random characters = exactly 20.
    return `T${stamp}${randomCode(5)}`
  }

  return `EP${stamp}${randomCode(6)}`
}
